"use client";

import { forwardRef, InputHTMLAttributes } from "react";
import { useFieldControl } from "../../system/field";
import { cn, swirskiAttrs } from "../../system";

export type InputVariant = "default" | "filled";
export type InputSize = "sm" | "md" | "lg";
export type InputTone = "default" | "danger";

export type InputProps = {
  variant?: InputVariant;
  /** Visual input height and padding. Defaults to md. */
  size?: InputSize;
  /** Border treatment. Use danger for error styling and aria-invalid for validation semantics. */
  tone?: InputTone;
} & Omit<InputHTMLAttributes<HTMLInputElement>, "size" | "color">;

const sizeStyles: Record<InputSize, string> = {
  sm: "h-10 px-3 text-sm",
  md: "h-12 px-4 text-base",
  lg: "h-14 px-5 text-lg",
};

const toneStyles: Record<InputTone, string> = {
  default: "border-[color:var(--sw-color-ink)]",
  danger: "border-[color:var(--sw-color-red)]",
};

export const Input = forwardRef<HTMLInputElement, InputProps>(
  (
    { className, variant = "default", size: sizeProp, tone: toneProp, ...props },
    ref,
  ) => {
    const { size: inheritedSize, readOnly, ...field } = useFieldControl(props);
    const size = sizeProp ?? inheritedSize ?? "md";
    const invalid = field["aria-invalid"] !== undefined && field["aria-invalid"] !== false && field["aria-invalid"] !== "false";
    const tone = toneProp ?? (invalid ? "danger" : "default");
    return (
      <input
        ref={ref}
        className={cn(
          "w-full border-[length:var(--sw-border-width)] font-bold text-[var(--sw-color-ink)] shadow-[4px_4px_0_var(--sw-color-shadow)] outline-none sw-motion-shift transition-all duration-[var(--sw-motion-fast,150ms)] placeholder:text-[color:var(--sw-color-muted)] hover:shadow-[6px_6px_0_var(--sw-color-shadow)] focus:-translate-y-0.5 focus:shadow-[6px_6px_0_var(--sw-color-focus)] focus:hover:shadow-[6px_6px_0_var(--sw-color-focus)] disabled:cursor-not-allowed disabled:bg-[var(--sw-color-paper)] disabled:text-[color:var(--sw-color-muted)] read-only:bg-[var(--sw-color-paper)] disabled:hover:shadow-[4px_4px_0_var(--sw-color-shadow)]",
          variant === "default"
            ? "bg-[var(--sw-color-surface)]"
            : "bg-[var(--sw-color-paper)]",
          sizeStyles[size],
          toneStyles[tone],
          className,
        )}
        {...swirskiAttrs("input", { size, tone, variant })}
        {...props}
          {...field}
          readOnly={readOnly}
      />
    );
  },
);

Input.displayName = "Input";

"use client";

import { forwardRef, useId, type ReactNode } from "react";
import { Field } from "./Field";
import { FieldError } from "./FieldError";
import { FieldHint } from "./FieldHint";
import { Input, type InputProps } from "./Input";
import { Label } from "./Label";

export type InputFieldProps = InputProps & {
  label: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  fieldClassName?: string;
};

/** A native input with a label and optional description and validation text. */
export const InputField = forwardRef<HTMLInputElement, InputFieldProps>(
  function InputField({ label, hint, error, id, fieldClassName, tone, ...props }, ref) {
    const generatedId = useId();
    const inputId = id ?? generatedId;
    const hintId = hint ? `${inputId}-hint` : undefined;
    const errorId = error ? `${inputId}-error` : undefined;
    const describedBy = [props["aria-describedby"], hintId, errorId]
      .filter(Boolean)
      .join(" ");

    return (
      <Field className={fieldClassName} controlId={inputId} size={props.size}>
        <Label htmlFor={inputId}>{label}</Label>
        <Input
          {...props}
          ref={ref}
          id={inputId}
          tone={tone ?? (errorId ? "danger" : undefined)}
          aria-describedby={describedBy || undefined}
          aria-invalid={props["aria-invalid"] ?? (errorId ? true : undefined)}
        />
        {hintId && <FieldHint id={hintId}>{hint}</FieldHint>}
        {errorId && <FieldError id={errorId}>{error}</FieldError>}
      </Field>
    );
  },
);

"use client";

import { LabelHTMLAttributes, forwardRef, useContext, useId } from "react";
import { FieldContext, useFieldPart } from "../../system/field";
import { cn, swirskiAttrs } from "../../system";

export type LabelVariant = "default" | "plain";
export type LabelSize = "sm" | "md" | "lg";
export type LabelTone = "default" | "muted" | "danger";

export type LabelProps = {
  variant?: LabelVariant;
  size?: LabelSize;
  tone?: LabelTone;
} & LabelHTMLAttributes<HTMLLabelElement>;

const sizeStyles: Record<LabelSize, string> = {
  sm: "text-xs",
  md: "text-sm",
  lg: "text-base",
};

const toneStyles: Record<LabelTone, string> = {
  default: "text-[var(--sw-color-ink)]",
  muted: "text-[var(--sw-color-muted)]",
  danger: "text-[color:var(--sw-color-red-text)]",
};

export const Label = forwardRef<HTMLLabelElement, LabelProps>(function Label(
  { className, children, id, htmlFor, variant = "default", size: sizeProp, tone = "default", ...props },
  ref,
) {
  const field = useContext(FieldContext);
  const generatedId = useId();
  const partId = id ?? (field ? generatedId : undefined);
  useFieldPart("label", partId);
  const size = sizeProp ?? field?.size ?? "md";
  return (
    <label
      ref={ref}
      id={partId}
      htmlFor={htmlFor ?? (field?.labelable === false ? undefined : field?.explicitControlId ?? field?.controlId)}
      className={cn(
        variant === "default" && "font-black uppercase tracking-wide",
        sizeStyles[size],
        toneStyles[tone],
        className,
      )}
      {...swirskiAttrs("label", { size, tone, variant })}
      {...props}
    >
      {children}
      {field?.required && <span aria-hidden="true" className="ml-1 text-[color:var(--sw-color-red-text)]">*</span>}
    </label>
  );
});

Label.displayName = "Label";

